/* VLOnto - downloads page (static table generated by scripts/site/build_site.py): copy buttons + ready flag. */
(function () {
  'use strict';
  var VL = window.VL, M = window.__VLONTO_METRICS;
  VL.chrome();
  M.page = 'downloads';
  document.addEventListener('click', function (e) {
    var b = e.target.closest('.copy-hash');
    if (b) VL.copy(b.getAttribute('data-hash'));
  });
  M.downloadRows = VL.$$('table.files tbody tr').length;
  VL.fontsReady().then(function () { VL.setReady(); });
})();
